var o=[{title:`Co opisują wzorce`,text:`Przysiad zgina i prostuje jednocześnie biodra, kolana i kostki. Zawias biodrowy to ruch głównie w biodrach, a wykroki i wejścia na podwyższenie obciążają jedną nogę naraz. Pchanie odsuwa opór od ciała, a ciągnięcie przybliża go do ciała. W noszeniu utrzymujesz ciężar stabilnie podczas chodzenia, ćwiczenia na mięśnie tułowia przeciwdziałają ruchowi tułowia lub go wywołują, a lokomocja obejmuje chodzenie, bieganie i podobne ruchy.`},{title:`Dlaczego wzorce mają znaczenie`,text:`Jedno ćwiczenie może angażować kilka mięśni i wzorców naraz. Przysiad kielichowy trenuje nogi i tułów, a noszenie ciężaru trenuje chwyt, postawę i mechanikę chodu. Porządkowanie ćwiczeń według wzorców pokazuje luki, które mogą umknąć na liście podzielonej tylko na klatkę, ramiona i nogi. Nie potrzebujesz każdego wzorca na każdym treningu.`},{title:`Zrównoważony tydzień`,text:`Podczas dwóch lub trzech treningów całego ciała początkujący może uwzględnić przysiad, zawias biodrowy, pchanie poziome, ciągnięcie poziome, wykrok i proste ćwiczenie przeciw rotacji lub przeciw wyprostowi. Pchanie pionowe, ciągnięcie pionowe i noszenie mogą dojść, gdy pozwalają na to Twój sprzęt, ruchomość i cele. Utrzymuj dawkę każdego wzorca na tyle małą, byś mógł się zregenerować, i pomijaj ćwiczenia, których nie potrzebujesz.`},{title:`Dopasuj wzorce do swoich możliwości`,text:`Każdy wzorzec ma łatwiejsze i trudniejsze warianty. Przysiad z krzesłem może poprzedzać przysiad kielichowy, a pompka przy ścianie pompkę na podłodze. Wiosłowanie na wyciągu i z hantlem to oba ciągnięcia poziome, ale wymagają innej równowagi i sprzętu. Jeśli ruch powoduje dyskomfort lub wydaje się niestabilny, zmień wariant i zachowaj wzorzec.`},{title:`Korzystanie z TrainUp`,text:`Strona każdego ćwiczenia w zakładce Ćwiczenia pokazuje jego wzorzec ruchowy, więc możesz sprawdzić, jak zaplanowany tydzień je pokrywa. Jeśli większość treningów ma pchanie, a prawie nie ma ciągnięcia, lukę wypełni wiosłowanie lub ściąganie pasujące do Twojego sprzętu i ograniczeń. Dąż do dobrego pokrycia w skali tygodni, a nie do idealnych proporcji na każdym treningu.`}];var a=[{label:`NSCA: bezpieczeństwo i podstawy treningu oporowego`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Biblioteka ćwiczeń ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:o,sources:a};export{n as default,o as sections,a as sources};